#!/bin/sh
# <SERVICE_NAME> client launcher - on-demand lifecycle (references/lifecycle.md).
# Generated by the podman-quadlet-service skill.
#
# Runs the real client command inside a transient systemd scope that Wants=
# and is ordered After= <SERVICE_NAME>.service. The container therefore starts
# with the first client (and is only "started" once healthy, via
# Notify=healthy), and StopWhenUnneeded=yes stops it once the last client
# scope is gone. Environment and stdio are inherited, so stdio protocols
# (MCP, LSP) pass through unchanged.
#
# Point EVERY client at this file. A client that runs <CLIENT_COMMAND>
# directly neither starts the container nor keeps it alive.
# OPTIONAL - only when the backend requires a token. The same podman secret
# feeds the container (Secret=) and the client (environment, never a file).
# DELETE when unused.
<CLIENT_VAR>="$(podman secret inspect --showsecret --format '{{.SecretData}}' <SECRET_NAME>)" || exit 1
export <CLIENT_VAR>

exec systemd-run --user --scope --quiet --collect \
  --unit="<SERVICE_NAME>-client-$$" \
  -p Wants=<SERVICE_NAME>.service \
  -p After=<SERVICE_NAME>.service \
  -- <CLIENT_COMMAND>
